/* sentence patterns with words inside (from templates) */
const AR_PATTERNS = [
 [/^The (.+) can't reach (.+)\.$/, m=>`الـ${tr(m[1])} مش بيوصل لـ${tr(m[2])}.`],
 [/^Too heavy: ([\d,]+) kg, but (the rocket lifts|\d+ launches lift) ([\d,]+) kg to (.+)\.$/, m=>`تقيلة أوي: ${m[1]} كجم، بس ${m[2].startsWith("the")?"الصاروخ بيشيل":m[2].split(" ")[0]+" إطلاقات بيشيلوا"} ${m[3]} كجم لـ${tr(m[4])}.`],
 [/^(.+) needs precise pointing\.$/, m=>`${m[1].split(", ").map(tr).join("، ")} محتاج توجيه دقيق.`],
 [/^(.+) on the pad\. Total mass ([\d,]+) kg\.$/, m=>`${tr(m[1].replace(/ \(×\d+ launches\)/,""))}${(m[1].match(/×(\d+)/)||["",""])[1]?` (${m[1].match(/×(\d+)/)[1]} إطلاقات)`:""} على منصة الإطلاق. الوزن الكلي ${m[2]} كجم.`],
 [/^The (.+) lifted off but could never reach (.+)\. It fell back\.$/, m=>`الـ${tr(m[1])} طلع بس عمره ما وصل لـ${tr(m[2])}. ورجع وقع.`],
 [/^The rocket strained under ([\d,]+) kg, ran out of fuel before orbit and fell into the ocean\.$/, m=>`الصاروخ اتعب تحت ${m[1]} كجم، والوقود خلص قبل المدار ووقع في المحيط.`],
 [/^It can lift only ([\d,]+) kg to (.+)\. Remove mass or choose a bigger rocket\.$/, m=>`بيشيل ${m[1]} كجم بس لـ${tr(m[2])}. شيل وزن أو اختار صاروخ أكبر.`],
 [/^(First pass through darkness|Systems switched on): power fell below what the (capsule|spacecraft) needs\. Batteries emptied and it went silent\.$/, m=>`${m[1].startsWith("First")?"أول ما دخلنا الضلمة":"أول ما الأنظمة اشتغلت"}: الكهربا بقت أقل من اللي ${m[2]==="capsule"?"الكبسولة":"المركبة"} محتاجاه. البطاريات فضيت وسكتت.`],
 [/^You made ([\d,]+) W on average but needed ([\d,]+) W\. Bigger panels, an RTG, or fewer power-hungry parts would fix it\.$/, m=>`كنت بتعمل ${m[1]} وات في المتوسط ومحتاج ${m[2]} وات. ألواح أكبر أو RTG أو قطع أقل بتاكل كهربا كانت هتحلها.`],
 [/^Power check: making ([\d,]+) W, using ([\d,]+) W\.$/, m=>`فحص الكهربا: بنعمل ${m[1]} وات، وبنستهلك ${m[2]} وات.`],
 [/^Battery too small for ([\d.]+) h of darkness \(needs ([\d,]+) Wh\)\.$/, m=>`البطارية صغيرة على ${m[1]} ساعة ضلمة (محتاجة ${m[2]} وات ساعة).`],
 [/^Battery too small for ([\d.]+) h of darkness: the spacecraft shuts down in every shadow\.$/, m=>`البطارية صغيرة على ${m[1]} ساعة ضلمة: المركبة بتطفي في كل ضل.`],
 [/^Your battery stored less than the ([\d,]+) Wh needed for each dark period, so you lost half your observing time\.$/, m=>`البطارية خزّنت أقل من الـ${m[1]} وات ساعة المطلوبين لكل فترة ضلمة، فخسرت نص وقت الرصد.`],
 [/^The spacecraft will shut down in every shadow: half the science\.$/, m=>`المركبة هتطفي في كل ضل: نص العلم بس.`],
 [/^Lead: (.+)$/, m=>`المسؤول: ${tr(m[1])}`],
 [/^Team chose ([A-D])$/, m=>`التيم اختار ${m[1]}`],
 [/^Decision: (.+?)\. (.+)$/, m=>`القرار: ${tr(m[1])}. ${tr(m[2])}`],
 [/^No decision in time: kept going\. (.+)$/, m=>`مفيش قرار في الوقت: كمّلنا. ${tr(m[1])}`],
 [/^ALERT: (.+)$/, m=>`تنبيه: ${tr(m[1])}`],
 [/^Locked: earn a star on (.+)$/, m=>`مقفولة: خد نجمة في "${tr(m[1])}" الأول`],
 [/^Mission complete: (.+)$/, m=>`المهمة نجحت: ${tr(m[1])}`],
 [/^Mission lost: (.+)$/, m=>`المهمة فشلت: ${tr(m[1])}`],
 [/^The real mission: (.+)$/, m=>`المهمة الحقيقية: ${tr(m[1])}`],
 [/^Yours: ([\d,]+) kg at launch, \$([\d,]+)M\.$/, m=>`بتاعتك: ${m[1]} كجم وقت الإطلاق، و$${m[2]} مليون.`],
 [/^starts as (.+?) \+ (.+)$/, m=>`يبدأ ${tr(m[1])} + ${tr(m[2])}`],
 [/^starts as (.+)$/, m=>`يبدأ ${tr(m[1])}`],
 [/^Reentry at ([\d.]+) km\/s: the heat shield was not rated for it\. The capsule would not survive\.$/, m=>`الدخول للغلاف الجوي بسرعة ${m[1]} كم/ث: الدرع الحراري مش معمول للسرعة دي. الكبسولة مكانتش هتعيش.`],
 [/^Your heat shield handles ([\d.]+) km\/s\. A (lunar|Mars)-return shield is needed\. \(In this game, the mission simply fails\.\)$/, m=>`الدرع الحراري بتاعك بيستحمل ${m[1]} كم/ث. محتاج درع ${m[2]==="lunar"?"للرجوع من القمر":"للرجوع من المريخ"}. (في اللعبة، المهمة بتفشل وبس.)`],
 [/^Day (\d+): supplies ran out\. Mission Control ordered an emergency return\.$/, m=>`يوم ${m[1]}: المؤن خلصت. غرفة التحكم أمرت برجوع طوارئ.`],
 [/^This path takes (\d+) days, but you packed supplies for (\d+)\. The crew must come home early and the mission fails\.$/, m=>`المسار ده بياخد ${m[1]} يوم، بس انت جبت مؤن لـ${m[2]} يوم بس. الرواد لازم يرجعوا بدري والمهمة تفشل.`],
 [/^IMPACT! The moonlet's orbit changed by ([\d.]+) minutes\.$/, m=>`خبطة! مدار القمر الصغير اتغير ${m[1]} دقيقة.`],
 [/^Your instruments made ([\d.,]+) GB a day but you could send only ([\d.,]+)\. A bigger antenna, more ground stations(, the Mars relay)? or compression would deliver more\.$/, m=>`أجهزتك طلّعت ${m[1]} جيجا في اليوم بس قدرت تبعت ${m[2]} بس. هوائي أكبر أو محطات أكتر${m[3]?" أو توصيل المريخ":""} أو ضغط كانوا هيوصلوا أكتر.`],
 [/^Only (\d+)% of the data made it to Earth\.$/, m=>`${m[1]}% بس من الداتا وصلت الأرض.`],
 [/^Money ran out after ([\d.]+) years\. Operations ended early\.$/, m=>`الفلوس خلصت بعد ${m[1]} سنة. الشغل وقف بدري.`],
 [/^Money runs out after ([\d.]+) of (\d+) years\.$/, m=>`الفلوس هتخلص بعد ${m[1]} من ${m[2]} سنين.`],
 [/^Over budget by \$([\d,]+)M\.$/, m=>`فوق الميزانية بـ$${m[1]} مليون.`],
 [/^The project goes over budget\.$/, m=>`المشروع هيعدي الميزانية.`],
 [/^([✓✗]) (.+)$/, m=>`${m[1]} ${tr(m[2])}`],
 [/^([A-D])$/, m=>m[1]],
 [/^Player (\d+) · starts as (.+)$/, m=>`لاعب ${m[1]} · ${tr("starts as "+m[2])}`],
 [/^(.+): (.+)$/, m=>{ const a=tr(m[1]), b=tr(m[2]); return (a!==m[1]||b!==m[2])?`${a}: ${b}`:null; }]
];
